<?php
namespace App\Controllers\Gestion;use App\Core\Controller;use App\Core\Request;use App\Core\Session;use App\Core\Database;use App\Models\Patient;use App\Models\Catalog;use Throwable;
class CitaController extends Controller{public function index(Request $r):void{$db=Database::connection();$s=$db->prepare('SELECT c.*,a.nombre AS paciente,ec.nombre AS estado,CONCAT(u.nombres," ",u.apellidos) AS profesional FROM citas c JOIN animales a ON a.id=c.animal_id JOIN estados_cita ec ON ec.id=c.estado_cita_id LEFT JOIN usuarios u ON u.id=c.profesional_id WHERE c.entorno_id=:e AND c.deleted_at IS NULL ORDER BY c.fecha_inicio DESC');$s->execute(['e'=>active_environment_id()]);$cat=new Catalog();$this->view('citas/index',['title'=>'Agenda','appointments'=>$s->fetchAll(),'patients'=>(new Patient())->allByEnvironment(active_environment_id()),'statuses'=>$cat->appointmentStatuses(),'professionals'=>$cat->users(),'success'=>Session::pullFlash('success'),'error'=>Session::pullFlash('error')]);}public function store(Request $r):void{if(!Session::validateCsrf($r->input('_token'))){http_response_code(419);return;}try{$db=Database::connection();$s=$db->prepare('INSERT INTO citas(entorno_id,animal_id,profesional_id,estado_cita_id,fecha_inicio,fecha_fin,motivo,observaciones,creado_por) VALUES(:e,:a,:p,:s,:fi,:ff,:m,:o,:u)');$s->execute(['e'=>active_environment_id(),'a'=>(int)$r->input('animal_id'),'p'=>$r->input('profesional_id')?(int)$r->input('profesional_id'):null,'s'=>(int)$r->input('estado_cita_id'),'fi'=>$this->dt($r->input('fecha_inicio')),'ff'=>$r->input('fecha_fin')?$this->dt($r->input('fecha_fin')):null,'m'=>trim((string)$r->input('motivo',''))?:null,'o'=>trim((string)$r->input('observaciones',''))?:null,'u'=>auth_id()]);(new \App\Services\AuditService())->log(auth_id(),active_environment_id(),'CITAS','CREAR','citas',(int)$db->lastInsertId());Session::flash('success','Cita creada.');}catch(Throwable $e){Session::flash('error',$e->getMessage());}$this->redirect('/citas');}private function dt($v):string{$v=str_replace('T',' ',(string)$v);return strlen($v)===16?$v.':00':$v;}}
